// ==UserScript==
// @name         Downfall of RTL
// @namespace    https://github.com/yappologistic/downfall-of-rtl
// @homepageURL  https://github.com/yappologistic/downfall-of-rtl
// @version      6.6.6
// @description  An LTR plugin for the RTL plugins. Forces every site back to left-to-right.
// @match        *://*/*
// @run-at       document-start
// @grant        none
// @noframes
// ==/UserScript==
// GENERATED by scripts/build.js from src/ — edit the source, not this file.

// Pick your fighter: 'polite' | 'spicy' | 'nuclear'
const LEVEL = 'spicy';

var DownfallOfRTL = (function () {
  var module = { exports: {} };
/*!
 * The Downfall of RTL — LTR Supremacy Engine™
 * Text goes left to right. That's it. That's the engine.
 * MIT licensed. No rights reserved, only lefts.
 */
(function (root, factory) {
  'use strict';
  const api = factory();
  if (typeof module === 'object' && module && module.exports) module.exports = api;
  else root.DownfallOfRTL = api;
})(typeof globalThis !== 'undefined' ? globalThis : this, function () {
  'use strict';

  const VERSION = '6.6.6';
  const LEVELS = ['polite', 'spicy', 'nuclear'];
  const STYLE_ID = 'downfall-of-rtl';
  const LAYER = 'downfall-of-rtl';
  const COMIC_SANS = '"Comic Sans MS", "Comic Neue", "Chalkboard SE", cursive';

  // ---------------------------------------------------------------------------
  // Unicode bidi controls. We don't delete them. We rehabilitate them.
  // Every RLM becomes an LRM, every RLE an LRE, and so on. Pairs stay balanced.
  // ---------------------------------------------------------------------------
  const BIDI_FLIP = {
    '\u200F': '\u200E', // RIGHT-TO-LEFT MARK      -> LEFT-TO-RIGHT MARK
    '\u061C': '\u200E', // ARABIC LETTER MARK      -> LEFT-TO-RIGHT MARK
    '\u202B': '\u202A', // RIGHT-TO-LEFT EMBEDDING -> LEFT-TO-RIGHT EMBEDDING
    '\u202E': '\u202D', // RIGHT-TO-LEFT OVERRIDE  -> LEFT-TO-RIGHT OVERRIDE
    '\u2067': '\u2066', // RIGHT-TO-LEFT ISOLATE   -> LEFT-TO-RIGHT ISOLATE
  };
  const RTL_CONTROLS = /[\u200F\u061C\u202B\u202E\u2067]/g;
  const ARABIC_SCRIPT = /[\u0600-\u06FF\u0750-\u077F\u08A0-\u08FF\uFB50-\uFDFF\uFE70-\uFEFF]/;

  function countRtlControls(text) {
    const m = String(text).match(RTL_CONTROLS);
    return m ? m.length : 0;
  }

  function flipBidiControls(text) {
    return String(text).replace(RTL_CONTROLS, (c) => BIDI_FLIP[c]);
  }

  // ---------------------------------------------------------------------------
  // The fonts every RTL plugin ships. Vazirmatn is in roughly 100% of them.
  // ---------------------------------------------------------------------------
  const PERSIAN_FONTS = [
    'Vazirmatn', 'Vazir', 'Sahel', 'Samim', 'Shabnam', 'Tanha', 'Parastoo', 'Gandom',
    'Nahid', 'Lalezar', 'Estedad', 'IRANSansX', 'IRANSans', 'IRANYekanX', 'IRANYekan',
    'Yekan Bakh', 'Yekan', 'Mikhak', 'Kalameh', 'Dana', 'Peyda', 'Shabnam',
    'B Nazanin', 'B Yekan', 'B Titr', 'B Mitra', 'Noto Naskh Arabic', 'Noto Sans Arabic',
    'Noto Nastaliq Urdu', 'Cairo', 'Tahoma Persian',
  ];
  const fontAlternation = [...new Set(PERSIAN_FONTS)]
    .sort((a, b) => b.length - a.length)
    .map((f) => f.replace(/[.*+?^${}()|[\]\\]/g, '\\$&').replace(/ /g, '[ -]?'))
    .join('|');
  const FONT_SUFFIX = '(?:[ -](?:FD|UI|RD|NL|WOL|Variable|Code|Thin|Light|Medium|Bold|Black))*';
  const persianFontRe = () =>
    new RegExp(`(["']?)(?:${fontAlternation})${FONT_SUFFIX}(?![\\w-])\\1`, 'gi');
  const HAS_PERSIAN_FONT = new RegExp(`(?:${fontAlternation})`, 'i');

  // Anything that smells like an RTL plugin wrote it.
  const RTL_MARKERS = /direction\s*:\s*rtl|unicode-bidi\s*:\s*plaintext|\[dir\s*=\s*["']?rtl|:dir\(\s*rtl/i;

  function looksRtlish(css) {
    return RTL_MARKERS.test(css) || HAS_PERSIAN_FONT.test(css);
  }

  // ---------------------------------------------------------------------------
  // Text rewriters (pure, used by the CLI and by the DOM engine)
  // ---------------------------------------------------------------------------

  /**
   * Rewrite CSS so it stops being RTL.
   * @param {string} css
   * @param {{fontReplacement?: string|null}} [opts] pass a font stack to replace
   *   Persian fonts with it (spicy mode uses Comic Sans, obviously).
   */
  function rewriteCss(css, opts) {
    const fontReplacement = opts && opts.fontReplacement;
    let out = String(css)
      .replace(/(\bdirection\s*:\s*)rtl\b/gi, '$1ltr')
      .replace(/(\bunicode-bidi\s*:\s*)plaintext\b/gi, '$1normal')
      .replace(/(\btext-align\s*:\s*)right\b/gi, '$1left');

    if (fontReplacement) {
      // Delete their @font-face rules for Persian fonts entirely...
      out = out.replace(/@font-face\s*\{[^}]*\}/gi, (block) =>
        HAS_PERSIAN_FONT.test(block) ? '/* @font-face deported by downfall-of-rtl */' : block
      );
      // ...then swap the names wherever someone still asks for them.
      out = out.replace(/(\bfont(?:-family)?\s*:)([^;}]*)/gi, (_, prop, value) =>
        prop + value.replace(persianFontRe(), fontReplacement)
      );
    }
    return out;
  }

  /**
   * Rewrite HTML / Markdown / anything with dir="" attributes, inline CSS,
   * Obsidian front matter (`direction: rtl`), or kramdown `{: dir="rtl"}`.
   */
  function rewriteMarkup(text, opts) {
    const fontReplacement = opts && opts.fontReplacement;
    let out = String(text).replace(
      /(\sdir\s*=\s*)(["']?)(?:rtl|auto)\2(?![\w-])/gi,
      (_, pre, q) => `${pre}${q || '"'}ltr${q || '"'}`
    );
    // style="..." attributes first, so the font stack's quotes don't close the attribute.
    out = out.replace(/(\sstyle\s*=\s*)(["'])([\s\S]*?)\2/gi, (_, pre, q, value) => {
      const safe = fontReplacement && fontReplacement.replace(/["']/g, q === '"' ? "'" : '"');
      return pre + q + rewriteCss(value, { fontReplacement: safe }) + q;
    });
    return flipBidiControls(rewriteCss(out, opts));
  }

  // ---------------------------------------------------------------------------
  // The stylesheet. Wrapped in a cascade layer, because of a beautiful quirk:
  // for !important declarations, *layered* rules beat *unlayered* ones,
  // regardless of specificity. RTL plugins inject unlayered CSS. They lose.
  // ---------------------------------------------------------------------------
  function buildCss(level, opts) {
    level = LEVELS.includes(level) ? level : 'spicy';
    const layer = !opts || opts.layer !== false;
    const fontFaces = !opts || opts.fontFaces !== false;

    const rules = [
      '*, *::before, *::after { direction: ltr !important; }',
      level === 'nuclear'
        ? // Every character, in the order it was typed, left to right. Persian
          // words render mirrored. You asked for nuclear.
          '*, *::before, *::after { unicode-bidi: bidi-override !important; }'
        : '*:not(bdo):not(bdi) { unicode-bidi: normal !important; }',
      '[dir="rtl" i], [dir="auto" i] { text-align: left !important; }',
      'input, textarea, [contenteditable] { direction: ltr !important; text-align: left !important; }',
    ];

    let css = layer ? `@layer ${LAYER} {\n  ${rules.join('\n  ')}\n}\n` : rules.join('\n') + '\n';

    if (level !== 'polite' && fontFaces) {
      // Font identity theft: define the Persian font names ourselves, pointing at Comic Sans.
      const local = 'local("Comic Sans MS"), local("ComicSansMS"), local("Comic Neue"), local("ComicNeue-Regular")';
      css += ['Vazirmatn', 'Vazir', 'Sahel', 'Samim', 'Shabnam', 'IRANSans', 'IRANSansX', 'Yekan', 'Estedad']
        .map((f) => `@font-face { font-family: "${f}"; src: ${local}; }`)
        .join('\n');
      css += '\n';
    }
    return css;
  }

  // ---------------------------------------------------------------------------
  // The DOM engine. Watches the page forever. RTL plugins re-apply? We re-apply.
  // ---------------------------------------------------------------------------
  const SKIP_TEXT = /^(SCRIPT|STYLE|TEXTAREA|INPUT|NOSCRIPT|CODE|PRE)$/;

  function newStats() {
    return { dirAttributes: 0, inlineStyles: 0, stylesheets: 0, bidiControls: 0, fonts: 0, alignments: 0 };
  }
  function total(stats) {
    return Object.keys(stats).reduce((n, k) => n + stats[k], 0);
  }

  /**
   * Unleash the engine on a document.
   * @param {{level?: string, doc?: Document, onStats?: (stats, total) => void}} [opts]
   * @returns {{stats: object, total: () => number, level: string, surrender: () => void}}
   */
  function unleash(opts) {
    opts = opts || {};
    const doc = opts.doc || document;
    const level = LEVELS.includes(opts.level) ? opts.level : 'spicy';
    const spicy = level !== 'polite';
    const stats = newStats();
    const seenDir = new WeakSet();
    const fontReplacement = spicy ? COMIC_SANS : null;
    let pending = new Set(); // whole subtrees
    let pendingSelf = new Set(); // just the element (attribute changes)
    let timer = null;
    let alive = true;

    // Claim the layer name as early as possible so ours is first in layer order.
    function ensureStyle() {
      let el = doc.getElementById(STYLE_ID);
      const css = buildCss(level);
      if (!el) {
        el = doc.createElement('style');
        el.id = STYLE_ID;
        el.setAttribute('data-level', level);
        (doc.head || doc.documentElement).prepend(el);
      }
      if (el.textContent !== css) el.textContent = css;
      return el;
    }

    const inEditable = (el) => !!(el.closest && el.closest('[contenteditable=""], [contenteditable="true"], [contenteditable="plaintext-only"], .cm-editor'));

    function hasOwnArabicText(el) {
      for (let n = el.firstChild; n; n = n.nextSibling) {
        if (n.nodeType === 3 && ARABIC_SCRIPT.test(n.nodeValue)) return true;
      }
      return false;
    }

    function processElement(el) {
      if (el.id === STYLE_ID) return;
      const tag = el.tagName;

      // 1. dir attributes. The CSS already overrules them; we just keep score.
      const dir = el.getAttribute && el.getAttribute('dir');
      if (dir && /^(rtl|auto)$/i.test(dir) && !seenDir.has(el)) {
        seenDir.add(el);
        stats.dirAttributes++;
      }

      // 2. Their <style> tags. Rewrite them in place.
      if (spicy && tag === 'STYLE') {
        const css = el.textContent;
        if (looksRtlish(css)) {
          const fixed = rewriteCss(css, { fontReplacement });
          if (fixed !== css) {
            el.textContent = fixed;
            stats.stylesheets++;
          }
        }
        return;
      }

      if (inEditable(el)) return; // never fight an editor's DOM, it fights back with your data

      // 3. Inline styles. style="direction: rtl !important" beats every stylesheet, so we go inline too.
      const st = el.style;
      if (st) {
        if (st.direction === 'rtl') {
          st.setProperty('direction', 'ltr', 'important');
          stats.inlineStyles++;
        }
        if (st.unicodeBidi === 'plaintext') {
          st.setProperty('unicode-bidi', 'normal', 'important');
          stats.inlineStyles++;
        }
        if (spicy && st.fontFamily && HAS_PERSIAN_FONT.test(st.fontFamily)) {
          st.setProperty('font-family', st.fontFamily.replace(persianFontRe(), fontReplacement), 'important');
          stats.fonts++;
        }
      }

      // 4. Persian text that someone right-aligned. Left. Now.
      if (hasOwnArabicText(el) && doc.defaultView) {
        const align = doc.defaultView.getComputedStyle(el).textAlign;
        if (align === 'right' || align === 'end' || align === '-webkit-right') {
          st.setProperty('text-align', 'left', 'important');
          stats.alignments++;
        }
      }

      // 5. Bidi control characters in text.
      if (spicy && !SKIP_TEXT.test(tag)) {
        for (let n = el.firstChild; n; n = n.nextSibling) {
          if (n.nodeType === 3) processText(n);
        }
      }
    }

    function processText(node) {
      const v = node.nodeValue;
      const c = countRtlControls(v);
      if (c) {
        node.nodeValue = flipBidiControls(v);
        stats.bidiControls += c;
      }
    }

    function processTree(rootNode) {
      if (rootNode.nodeType === 3) {
        const p = rootNode.parentElement;
        if (spicy && p && !SKIP_TEXT.test(p.tagName) && !inEditable(p)) processText(rootNode);
        return;
      }
      if (rootNode.nodeType !== 1 && rootNode.nodeType !== 9) return;
      const start = rootNode.nodeType === 9 ? rootNode.documentElement : rootNode;
      if (!start) return;
      processElement(start);
      const all = start.getElementsByTagName('*');
      for (let i = 0; i < all.length; i++) processElement(all[i]);
    }

    let lastTotal = -1;
    function flush() {
      timer = null;
      if (!alive) return;
      const batch = pending;
      const selfBatch = pendingSelf;
      pending = new Set();
      pendingSelf = new Set();
      ensureStyle();
      for (const node of batch) if (node.isConnected) processTree(node);
      for (const el of selfBatch) if (el.isConnected && !batch.has(el)) processElement(el);
      const t = total(stats);
      if (t !== lastTotal) {
        lastTotal = t;
        if (opts.onStats) opts.onStats(stats, t);
      }
    }

    function schedule(node, shallow) {
      (shallow ? pendingSelf : pending).add(node);
      // setTimeout, not rAF: background tabs deserve LTR too.
      if (!timer) timer = setTimeout(flush, 30);
    }

    const observer = new MutationObserver((records) => {
      for (const r of records) {
        if (r.type === 'childList') {
          r.addedNodes.forEach((n) => schedule(n));
          r.removedNodes.forEach((n) => { if (n.id === STYLE_ID) schedule(doc); });
          if (r.target.nodeName === 'STYLE') schedule(r.target);
        } else if (r.type === 'characterData') {
          schedule(r.target);
        } else {
          schedule(r.target, true);
        }
      }
    });

    ensureStyle();
    observer.observe(doc, {
      childList: true,
      subtree: true,
      characterData: spicy,
      attributes: true,
      attributeFilter: ['dir', 'style'],
    });
    schedule(doc);

    return {
      level,
      stats,
      total: () => total(stats),
      /** Removes the stylesheet and stops watching. Inline fixes stay; reload for full RTL restoration. */
      surrender() {
        alive = false;
        observer.disconnect();
        if (timer) clearTimeout(timer);
        const el = doc.getElementById(STYLE_ID);
        if (el) el.remove();
      },
    };
  }

  return {
    VERSION,
    LEVELS,
    COMIC_SANS,
    PERSIAN_FONTS,
    countRtlControls,
    flipBidiControls,
    rewriteCss,
    rewriteMarkup,
    looksRtlish,
    buildCss,
    unleash,
  };
});

  return module.exports;
})();

DownfallOfRTL.unleash({ level: LEVEL });
